<script setup>
import { ref, computed, watch } from 'vue'
const key='pega-peso-mulher-mvp-v1'
const initial={routine:[{name:'Descanso',cardio:0},{name:'Quadríceps',cardio:30},{name:'Superiores A',cardio:30},{name:'Descanso',cardio:0},{name:'Posterior e glúteos',cardio:30},{name:'Superiores B',cardio:30},{name:'Cardio',cardio:30}],workouts:[{name:'Quadríceps',exercises:['Agachamento livre','Leg press','Cadeira extensora']},{name:'Superiores A',exercises:['Puxada alta','Remada baixa']},{name:'Posterior e glúteos',exercises:['Stiff','Mesa flexora','Elevação pélvica']},{name:'Superiores B',exercises:['Supino máquina','Elevação lateral']}],history:[]}
let saved;try{saved=JSON.parse(localStorage.getItem(key))}catch{}
const state=ref(saved&&saved.routine&&saved.workouts?saved:initial)
watch(state,v=>localStorage.setItem(key,JSON.stringify(v)),{deep:true})
const view=ref('home'),today=new Date().getDay(),day=ref(today),editDay=ref(today)
const weekdays=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado']
const short=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb']
const current=computed(()=>state.value.routine[day.value])
const editName=ref(''),editCardio=ref(0)
function edit(d){editDay.value=d;editName.value=state.value.routine[d].name;editCardio.value=state.value.routine[d].cardio;view.value='edit'}
function saveRoutine(){state.value.routine[editDay.value]={name:editName.value.trim()||'Descanso',cardio:Math.max(0,Number(editCardio.value)||0)};day.value=editDay.value;view.value='home'}
const workoutName=ref(''),newWorkout=ref(''),newExercise=ref('')
const createModal=ref(false),createError=ref('')
function openCreateModal(){newWorkout.value='';createError.value='';createModal.value=true}
const workout=computed(()=>state.value.workouts.find(w=>w.name===workoutName.value))
function openWorkout(name){workoutName.value=name;view.value='workout'}
function addWorkout(){const n=newWorkout.value.trim();if(!n){createError.value='Digite o nome do treino.';return}if(state.value.workouts.some(w=>w.name.toLowerCase()===n.toLowerCase())){createError.value='Você já tem um treino com esse nome.';return}state.value.workouts.push({name:n,exercises:[]});createModal.value=false;newWorkout.value='';createError.value='';openWorkout(n)}
function addExercise(){let n=newExercise.value.trim();if(!n||!workout.value)return;workout.value.exercises.push(n);newExercise.value=''}
const started=ref(null),finished=ref(null),kind=ref('forca'),exercise=ref(''),kg=ref(''),reps=ref('10'),sets=ref({}),completed=ref([])
const clock=ref(Date.now());let ticker=null
function start(k){kind.value=k;started.value=Date.now();clock.value=Date.now();finished.value=null;sets.value={};completed.value=[];view.value='session';if(ticker)clearInterval(ticker);ticker=setInterval(()=>clock.value=Date.now(),1000)}
const elapsed=computed(()=>started.value?Math.max(0,Math.floor(((finished.value||clock.value)-started.value)/1000)):0)
const time=computed(()=>[Math.floor(elapsed.value/3600),Math.floor(elapsed.value%3600/60),elapsed.value%60].map(n=>String(n).padStart(2,'0')).join(':'))
function maxFor(e){return Math.max(0,...state.value.history.flatMap(h=>(h.sets[e]||[]).map(s=>s.kg)),...(sets.value[e]||[]).map(s=>s.kg))}
function lastFor(e){const a=state.value.history.flatMap(h=>h.sets[e]||[]);return a.length?a[a.length-1].kg:0}
function choose(e){exercise.value=e;kg.value=String(lastFor(e)||'');reps.value='10';view.value='exercise'}
function addSet(){const k=Number(kg.value),r=Number(reps.value);if(!(k>=0&&r>0&&kg.value!==''))return;sets.value={...sets.value,[exercise.value]:[...(sets.value[exercise.value]||[]),{kg:k,reps:r}]}}
function finish(){finished.value=Date.now();if(ticker){clearInterval(ticker);ticker=null}state.value.history.push({date:new Date().toLocaleDateString('pt-BR'),name:kind.value==='cardio'?'Cardio':workoutName.value,kind:kind.value,seconds:elapsed.value,sets:JSON.parse(JSON.stringify(sets.value))});view.value='done'}
const selectedStat=ref('all')
const statsPeriod=ref('all')
const statsSessions=computed(()=>state.value.history.filter(h=>statsPeriod.value==='all'||h.kind===statsPeriod.value))
const allExercises=computed(()=>[...new Set(state.value.workouts.flatMap(w=>w.exercises))])
const exerciseStats=computed(()=>state.value.history.flatMap(h=>Object.entries(h.sets||{}).flatMap(([name,ss])=>ss.map(s=>({name,kg:s.kg,reps:s.reps,date:h.date})))))
const bestExercise=computed(()=>exerciseStats.value.filter(s=>selectedStat.value==='all'||s.name===selectedStat.value))
const maxLoad=computed(()=>Math.max(0,...bestExercise.value.map(s=>s.kg)))
const totalVolume=computed(()=>bestExercise.value.reduce((a,s)=>a+s.kg*s.reps,0))
const completedSessions=computed(()=>statsSessions.value.length)
const cycleKey='pega-peso-mulher-cycle-v1'
let cycleSaved;try{cycleSaved=JSON.parse(localStorage.getItem(cycleKey))}catch{}
const cycle=ref(cycleSaved||{enabled:false,start:'',length:28,period:5,notes:[]})
watch(cycle,v=>localStorage.setItem(cycleKey,JSON.stringify(v)),{deep:true})
const noteDate=ref(new Date().toISOString().slice(0,10)),noteEnergy=ref('normal'),noteSymptoms=ref(''),noteDifficulty=ref('normal')
const cycleDay=computed(()=>{if(!cycle.value.start)return null;const diff=Math.floor((new Date().setHours(12,0,0,0)-new Date(cycle.value.start+'T12:00:00').getTime())/86400000);return ((diff%Math.max(1,cycle.value.length))+Math.max(1,cycle.value.length))%Math.max(1,cycle.value.length)+1})
function addNote(){cycle.value.notes.unshift({date:noteDate.value,energy:noteEnergy.value,symptoms:noteSymptoms.value,difficulty:noteDifficulty.value});noteSymptoms.value=''}
const weeklyCardio=computed(()=>state.value.routine.reduce((a,r)=>a+Number(r.cardio||0),0))
</script>
<template>
<div class="app"><header><div><small>🐕 PEGA PESO, MULHER!</small><h1>{{view==='home'?'Bora treinar, mulher!':view==='edit'?'Editar rotina':view==='list'?'Meus treinos':view==='stats'?'Minha evolução':view==='cycle'?'Meu ciclo':view==='routine'?'Minha semana':view==='done'?'Treino pago!':workoutName||'Seu treino'}}</h1></div><span class="chair">🪑</span></header>
<main>
<template v-if="view==='home'"><div class="top"><div><small>HOJE É</small><h2>{{weekdays[day]}}</h2></div><button class="outline" @click="edit(day)">✏️ Editar rotina</button></div>
<div class="week"><button v-for="(d,i) in short" :key="i" :class="{selected:day===i}" @click="day=i">{{d}}<span>{{state.routine[i].name==='Descanso'?'–':'●'}}</span></button></div>
<section class="pink"><small>🏋️ TREINO DO DIA</small><h2>{{current.name}}</h2><button v-if="current.name!=='Descanso'&&current.name!=='Cardio'" @click="openWorkout(current.name)">Ver treino e iniciar →</button><p v-else>Sem musculação planejada neste dia.</p></section>
<section v-if="current.cardio>0" class="green"><small>🏃 CARDIO DO DIA</small><h2>{{current.cardio}} minutos</h2><button @click="start('cardio')">▶ Iniciar cardio</button></section>
<div class="cardio-compact"><span>🏃 Cardio na semana</span><b>{{weeklyCardio}} / 150 min</b></div>
<button class="outline full" @click="view='list'">Gerenciar meus treinos →</button></template>
<template v-else-if="view==='routine'"><div class="section-heading"><h2>Planejamento semanal</h2><p class="muted">Musculação e cardio, juntos ou em horários diferentes.</p></div><section class="soft"><small>🏃 CARDIO PLANEJADO NA SEMANA</small><h2>{{weeklyCardio}} min</h2><div class="bar"><div :style="{width:Math.min(100,weeklyCardio/150*100)+'%'}"></div></div><small>150 minutos semanais de atividade moderada são uma referência geral, não um limite.</small></section><div v-for="(r,i) in state.routine" :key="i" class="item" @click="edit(i)"><div><b>{{weekdays[i]}}</b><small>🏋️ {{r.name}} · 🏃 {{r.cardio}} min de cardio</small></div><span>✏️</span></div><button class="outline" @click="view='list'">Gerenciar meus treinos</button></template>
<template v-else-if="view==='stats'"><div class="section-heading"><h2>Sua evolução 💪</h2><p class="muted">Seus números, no seu ritmo.</p></div><div class="stats"><section class="pink"><small>🏆 Maior carga</small><h2>{{maxLoad}} kg</h2></section><section class="green"><small>📊 Volume registrado</small><h2>{{totalVolume.toLocaleString('pt-BR')}} kg</h2></section></div><section class="soft"><small>SESSÕES FINALIZADAS</small><h2>{{state.history.length}}</h2><p class="muted">Musculação e cardio registrados neste navegador.</p></section><label>Filtrar por exercício</label><select v-model="selectedStat"><option value="all">Todos os exercícios</option><option v-for="e in allExercises" :key="e" :value="e">{{e}}</option></select><h3>Histórico de cargas</h3><div v-if="!bestExercise.length" class="empty">Ainda não há séries registradas. Termine um treino para começar a acompanhar sua evolução! 🐕</div><div v-for="(s,i) in [...bestExercise].reverse().slice(0,25)" :key="i" class="item"><div><b>{{s.name}}</b><small>{{s.date}}</small></div><span>{{s.kg}} kg × {{s.reps}}</span></div><h3>Treinos recentes</h3><div v-for="(h,i) in [...state.history].reverse().slice(0,10)" :key="i" class="item"><div><b>{{h.name}}</b><small>{{h.date}}</small></div><span>{{Math.round(h.seconds/60)}} min</span></div></template>
<template v-else-if="view==='cycle'"><div class="section-heading"><h2>Meu ciclo 🌸</h2><p class="muted">Registro opcional e privado neste navegador.</p></div><section class="pink"><b>🌷 Acompanhamento menstrual</b><p>Você decide se quer acompanhar seu ciclo e relacionar como se sentiu aos treinos.</p><label class="switchline"><input type="checkbox" v-model="cycle.enabled"/> Ativar acompanhamento</label></section><template v-if="cycle.enabled"><label>Primeiro dia da última menstruação</label><input type="date" v-model="cycle.start"/><div class="stats"><div><label>Ciclo médio (dias)</label><input type="number" min="15" max="60" v-model.number="cycle.length"/></div><div><label>Duração da menstruação</label><input type="number" min="1" max="15" v-model.number="cycle.period"/></div></div><section class="green" v-if="cycleDay"><small>DIA ESTIMADO DO CICLO</small><h2>Dia {{cycleDay}}</h2><p class="muted">Estimativa baseada nas datas informadas. Não serve como método contraceptivo ou diagnóstico.</p></section><h3>Como você está hoje?</h3><label>Data</label><input type="date" v-model="noteDate"/><label>Energia</label><select v-model="noteEnergy"><option value="baixa">Baixa</option><option value="normal">Normal</option><option value="alta">Alta</option></select><label>Dificuldade percebida no treino</label><select v-model="noteDifficulty"><option value="leve">Leve</option><option value="normal">Normal</option><option value="pesada">Pesada</option></select><label>Sintomas / observações</label><textarea v-model="noteSymptoms" placeholder="Opcional: cólica, disposição, humor..."></textarea><button @click="addNote">Salvar registro</button><h3>Registros anteriores</h3><div v-for="(n,i) in cycle.notes" :key="i" class="item"><div><b>{{n.date}} · Energia {{n.energy}}</b><small>{{n.symptoms||'Sem observações'}} · Treino {{n.difficulty}}</small></div></div></template><p class="muted">Esses registros não são enviados para um servidor nesta versão. Evite usar em dispositivos compartilhados.</p></template>
<template v-else-if="view==='edit'"><button class="back" @click="view='home'">← Voltar</button><label>Dia da semana</label><select v-model.number="editDay" @change="edit(editDay)"><option v-for="(d,i) in weekdays" :key="i" :value="i">{{d}}</option></select><label>Treino de força</label><select v-model="editName"><option value="Descanso">Descanso</option><option v-for="w in state.workouts" :key="w.name" :value="w.name">{{w.name}}</option><option value="Cardio">Somente cardio</option></select><label>Cardio planejado (minutos)</label><input v-model.number="editCardio" type="number" min="0" step="5"/><button @click="saveRoutine">Salvar alterações</button><p class="muted">Você pode alterar a rotina sempre que precisar.</p></template>
<template v-else-if="view==='list'"><div class="top list-heading"><div><h2>Meus treinos</h2><small>{{state.workouts.length}} treinos cadastrados</small></div><button @click="openCreateModal">＋ Criar treino</button></div><div class="compact-list"><div v-for="w in state.workouts" :key="w.name" class="item compact-item" @click="openWorkout(w.name)"><div><b>{{w.name}}</b><small>{{w.exercises.length}} exercícios</small></div><span>›</span></div></div></template>
<template v-else-if="view==='workout'"><button class="back" @click="view='home'">← Início</button><h2>{{workoutName}}</h2><section v-if="workout"><div class="item" v-for="e in workout.exercises" :key="e"><b>{{e}}</b><small>Recorde: {{maxFor(e)}} kg</small></div><label>Adicionar exercício</label><input v-model="newExercise" placeholder="Nome do exercício"/><button class="outline" @click="addExercise">+ Adicionar exercício</button></section><button @click="start('forca')">▶ Iniciar treino</button></template>
<template v-else-if="view==='session'"><section class="timer"><small>TEMPO TOTAL</small><h2>{{time}}</h2></section><template v-if="kind==='cardio'"><h2>🏃 Cardio em andamento</h2><p>Seu cronômetro continua contando.</p></template><template v-else><h3>Escolha o exercício</h3><div class="item" v-for="e in (workout?.exercises||[])" :key="e" @click="choose(e)"><div><b>{{e}}</b><small>{{(sets[e]||[]).length}} séries · Máximo {{maxFor(e)}} kg</small></div><span>{{completed.includes(e)?'✓':'→'}}</span></div></template><button class="outline" @click="finish">✓ Finalizar sessão</button></template>
<template v-else-if="view==='exercise'"><button class="back" @click="view='session'">← Exercícios</button><section class="timer"><small>TEMPO TOTAL</small><h2>{{time}}</h2></section><h2>{{exercise}}</h2><div class="stats"><section class="pink"><small>🏆 Recorde</small><h2>{{maxFor(exercise)}} kg</h2></section><section class="soft"><small>Último peso</small><h2>{{lastFor(exercise)}} kg</h2></section></div><h3>Séries de hoje</h3><div class="item" v-for="(s,i) in (sets[exercise]||[])" :key="i"><span>✓ {{i+1}}ª série</span><b>{{s.kg}} kg × {{s.reps}}</b><button class="mini" @click="sets[exercise].splice(i,1)">✕</button></div><div class="stats"><div><label>Peso (kg)</label><input type="number" min="0" v-model="kg"/></div><div><label>Repetições</label><input type="number" min="1" v-model="reps"/></div></div><button @click="addSet">+ Adicionar série</button><button class="outline" @click="completed.includes(exercise)?null:completed.push(exercise);view='session'">✓ Concluir exercício</button></template>
<template v-else-if="view==='done'"><div class="celebrate"><span>🏆🐕🪑</span><h2>Treino concluído!</h2><h1>{{time}}</h1><p>{{Object.values(sets).reduce((a,s)=>a+s.length,0)}} séries registradas</p></div><button @click="view='home'">Voltar ao início</button></template>
</main><div v-if="createModal" class="modal-backdrop" @click.self="createModal=false"><div class="modal-sheet" role="dialog" aria-modal="true" aria-label="Criar novo treino"><div class="modal-head"><div><small>NOVO TREINO</small><h2>Criar treino 💪</h2></div><button class="close-modal" aria-label="Fechar" @click="createModal=false">✕</button></div><p class="muted">Dê um nome ao seu treino. Depois você poderá adicionar os exercícios.</p><form @submit.prevent="addWorkout"><label for="new-workout-name">Nome do treino</label><input id="new-workout-name" v-model="newWorkout" placeholder="Ex.: Glúteos e posterior" maxlength="60" autofocus/><p v-if="createError" class="field-error">{{createError}}</p><div class="modal-actions"><button type="button" class="outline" @click="createModal=false">Cancelar</button><button type="submit">Criar treino</button></div></form></div></div><nav class="bottom-nav" aria-label="Navegação principal"><button v-for="tab in [{id:'home',icon:'🏠',label:'Início'},{id:'list',icon:'🏋️',label:'Treinos'},{id:'routine',icon:'📅',label:'Rotina'},{id:'stats',icon:'📈',label:'Evolução'},{id:'cycle',icon:'🌸',label:'Ciclo'}]" :key="tab.id" :class="{active:view===tab.id}" @click="view=tab.id"><span>{{tab.icon}}</span><small>{{tab.label}}</small></button></nav><footer>Protótipo local · dados salvos apenas neste navegador · sem cadastro ou sincronização</footer></div>
</template>